def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    my_prev, opp_prev = history[-1]
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c

    if n < 5:
        return 'C'

    if n >= 95:
        if opp_d <= 2 and my_d <= 2:
            return 'C'
        if opp_prev == 'D' and opp_d >= 5:
            return 'D'
        if opp_prev == 'D':
            return 'C'
        if opp_d > my_d + 2:
            return 'D'
        return 'C'

    if n >= 80:
        if opp_d <= 3:
            return 'C'
        if opp_prev == 'D' and opp_d >= 8:
            return 'D'
        if opp_d * 3 > n * 2:
            return 'D'
        return 'C'

    if n < 10:
        return 'C'

    # detect always defect / high defection
    if opp_d >= n - 2 and n >= 8:
        return 'D'

    # detect always cooperate
    if opp_d == 0:
        if n >= 20 and my_d == 0:
            return 'D'
        return 'C'

    # provocative/prober responses with noise-free assumption
    if opp_prev == 'D':
        # retaliate but be somewhat forgiving if opponent mostly cooperates
        if opp_d <= max(2, n // 10):
            return 'C'
        return 'D'

    # opponent cooperated last
    if opp_d >= n // 2 and n >= 8:
        return 'D'
    if opp_d * 4 >= n and n >= 12:
        return 'D'
    if my_d >= 2 and opp_d <= 1:
        return 'D'
    return 'C'

